def get_X(a, b):
    X = []
    for n in range(a * b + 1):
        is_representable = False
        for i in range(a + 1):
            for j in range(b + 1):
                if i * a + j * b == n:
                    is_representable = True
                    break
            if is_representable:
                break
        if not is_representable:
            X.append(n)
    return X

X = get_X(11, 20)
print(f"Number of elements in X: {len(X)}")
print(f"X: {X}")

def count_upward_closed(X, a, b):
    # X is the set of non-representable integers
    # An upward-closed subset K of X satisfies:
    # if x in K and x+a in X, then x+a in K
    # if x in K and x+b in X, then x+b in K

    # We can represent each K as a bitmask of X
    n = len(X)
    count = 0
    for i in range(1 << n):
        K = []
        for j in range(n):
            if (i >> j) & 1:
                K.append(X[j])

        is_closed = True
        for x in K:
            if x + a in X and x + a not in K:
                is_closed = False
                break
            if x + b in X and x + b not in K:
                is_closed = False
                break

        if is_closed:
            count += 1
    return count

